BattleRom_PcKoFrame:
    incbin "../../build/records/BattleRom_PcKoFrame.bin"          ; records: table 28 x 1 B

; $D1:5F5E-$D1:5FFF (162 B), unknown, unknown: 162 B after BattleRom_PcKoFrame (past its
; reader's 28 records)
