BattleRom_FxColours:
    incbin "../../build/assets/palette/BattleRom_FxColours.bin"

; $D1:6240-$D1:646B (556 B), table, confirmed: 4 B per layer effect: script ids
; Read by BattleCD_LoadLayerFx.
